const CONCEALED = [
  'org.nspasteboard.ConcealedType',
  'org.nspasteboard.TransientType',
  'org.nspasteboard.AutoGeneratedType'
]
const MAX_TEXT = 10_000

/**
 * Opt-in, in-memory clipboard history (never written to disk, gone on quit). macOS has no
 * clipboard-change event, so while enabled it polls once a second. Items that password managers
 * mark as concealed/transient are skipped.
 */
export function createClipboardHistory({ clipboard, now = Date.now, max = 50, intervalMs = 1000 }) {
  let items = []
  let seq = 0
  let lastSeen = null
  let timer = null

  function tick() {
    let text
    try {
      const formats = clipboard.availableFormats()
      if (formats.some((f) => CONCEALED.includes(f))) {
        lastSeen = null
        return
      }
      text = clipboard.readText()
    } catch {
      return
    }
    if (!text || !text.trim() || text.length > MAX_TEXT || text === lastSeen) return
    lastSeen = text
    items = [{ id: ++seq, text, at: now() }, ...items.filter((i) => i.text !== text)].slice(0, max)
  }

  return {
    tick,
    isRunning: () => timer !== null,
    start() {
      if (timer) return
      const current = clipboard.readText()
      lastSeen = current || null // what is already on the clipboard when enabled is not recorded
      timer = setInterval(tick, intervalMs)
    },
    stop() {
      if (timer) clearInterval(timer)
      timer = null
      items = []
      lastSeen = null
    },
    list(query = '', limit = 30) {
      const q = String(query).trim().toLowerCase()
      return items.filter((i) => !q || i.text.toLowerCase().includes(q)).slice(0, limit)
    },
    /** Put an item back on the clipboard. */
    copy(id) {
      const item = items.find((i) => i.id === id)
      if (!item) return false
      lastSeen = item.text
      clipboard.writeText(item.text)
      return true
    },
    clear() {
      const n = items.length
      items = []
      return n
    }
  }
}
